def is_square_free(n):
    if n == 1:
        return True
    i = 2
    while i * i <= n:
        if n % (i * i) == 0:
            return False
        i += 1
    return True

def find_all_solutions():
    solutions = set()
    # The condition is K = 1001 * (uv + vw + wu) / (m^2 * (uvw)^2)
    # Where a = m*u^2, b = m*v^2, c = m*w^2.
    # We require K to be a positive integer.
    # This is equivalent to:
    # m^2 * (uvw)^2 must divide 1001 * (uv + vw + wu).
    # Let Q = 1001 * (uv + vw + wu) / (uvw)^2.
    # For a given (u, v, w), if Q is an integer, 
    # then we need to find all square-free m such that m^2 | Q.

    for u in range(1, 55): 
        max_vw = 3003 // (u*u)
        for v in range(1, 1000):
            if v > max_vw: break
            max_w = max_vw // v
            for w in range(1, max_w + 1):
                numerator = 1001 * (u*v + v*w + w*u)
                denominator = (u * v * w) ** 2

                if numerator % denominator == 0:
                    Q = numerator // denominator
                    for m in range(1, int(Q**0.5) + 1):
                        if Q % (m*m) == 0:
                            if is_square_free(m):
                                solutions.add((m*u*u, m*v*v, m*w*w))
    return len(solutions)

